// Cold-session initialization only: latch startup after GP/HP resets settle.
// Later software/domain reset is a fault, never a new DDR completion proof.
(* ASYNC_REG="TRUE" *) reg [1:0] user_hp_reset_sync=2'b11;
reg [3:0] user_boot_count=0;
reg user_session_up=0;
always @(posedge gp_clk or posedge sys_rst)begin
 if(sys_rst)begin user_hp_reset_sync<=2'b11;user_boot_count<=0;user_session_up<=0;end
 else begin
  user_hp_reset_sync<={user_hp_reset_sync[0],hp_clk_rst};
  if(!user_session_up)begin
   if(gp_clk_rst || user_hp_reset_sync[1])user_boot_count<=0;
   else if(user_boot_count==15)user_session_up<=1;
   else user_boot_count<=user_boot_count+1;
  end
 end
end
g_bench_endpoint U_window_ddr(
 .por_n(user_session_up && !sys_rst),.c_clk(gp_clk),.d_clk(hp_clk),
 .fault_event(gp_clk_rst|hp_clk_rst),
 .reg_awaddr(User_Reg_awwaddr),.reg_awdata(User_Reg_awwdata),
 .reg_awvalid(User_Reg_awwvalid),.reg_awready(User_Reg_awwready),
 .reg_araddr(User_Reg_araddr),.reg_arvalid(User_Reg_arvalid),.reg_arready(User_Reg_arready),
 .reg_rdata(User_Reg_rdata),.reg_rvalid(User_Reg_rvalid),.reg_rready(User_Reg_rready),
 .awwaddr(User_Ddr_awwaddr),.awwdata(User_Ddr_awwdata),.awwinfo(User_Ddr_awwinfo),
 .awwvalid(User_Ddr_awwvalid),.awwready(User_Ddr_awwready),
 .araddr(User_Ddr_araddr),.arinfo(User_Ddr_arinfo),.arvalid(User_Ddr_arvalid),.arready(User_Ddr_arready),
 .rdata(User_Ddr_rdata),.rinfo(User_Ddr_rinfo),.rvalid(User_Ddr_rvalid),.rready(User_Ddr_rready),
 .PL_PHY_RX_CLK(PL_PHY_RX_CLK),.PL_PHY_RXD(PL_PHY_RXD),.PL_PHY_RX_CTRL(PL_PHY_RX_CTRL),
 .PL_PHY_TX_CLK(PL_PHY_TX_CLK),.PL_PHY_TXD(PL_PHY_TXD),.PL_PHY_TX_CTRL(PL_PHY_TX_CTRL),
 .PL_PHY_MDC(PL_PHY_MDC),.PL_PHY_MDIO(PL_PHY_MDIO),.PL_PHY_RESET(PL_PHY_RESET));

